const firebaseData = $input.first().json;

const tasks = Object.values(firebaseData ?? {});

const ids = tasks
  .map(task => task?.id)
  .filter(id =>
    typeof id === "number" &&
    Number.isInteger(id)
  );

const nextId = ids.length
  ? Math.max(...ids) + 1
  : 0;

return [{
  json: {
    nextId
  }
}];

const nextId = $input.first().json.nextId;

if (!Number.isInteger(nextId)) {
  throw new Error("Invalid ticket ID");
}

// Get the ticket from whichever branch was executed.
let ticket;

if ($('Merge').first().json) {
  ticket = $('Merge').first().json;
}

if (!ticket || !ticket.title) {
  throw new Error("No valid ticket data found");
}

return [{
  json: {
    ...ticket,
    id: nextId,
    firebaseId: null,
    dueDate: ticket.dueDate ?? ""
  }
}];

