parameters.jsCode:
const ticket = $input.first().json.output;

if (!ticket || typeof ticket !== "object" || Array.isArray(ticket)) {
  throw new Error("AI Agent returned no valid ticket object");
}

const requiredFields = [
  "title",
  "description",
  "category",
  "priority",
  "dueDate",
  "subtasks"
];

for (const field of requiredFields) {
  if (!(field in ticket)) {
    throw new Error(`Missing ticket field: ${field}`);
  }
}

return [
  {
    json: ticket
  }
];
